<script setup lang="ts">
import { ArrowRight, CheckCircle2, Eye, EyeOff, LockKeyhole } from '@lucide/vue'
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
const route=useRoute();const router=useRouter();const visible=ref(false);const loading=ref(false);const error=ref('');const form=reactive({token:String(route.params.token),email:String(route.query.email||''),password:'',password_confirmation:''})
async function submit(){loading.value=true;error.value='';try{await api.post('/reset-password',form);router.replace('/login?reset=1')}catch(e:any){const errors=e.response?.data?.errors;error.value=errors?Object.values(errors).flat().join(' '):(e.response?.data?.message||'We could not reset your password.')}finally{loading.value=false}}
</script>
<template><main class="auth-layout"><section class="auth-story"><BrandLogo light/><div class="story-copy"><span class="eyebrow light">CREATE A FRESH PASSWORD</span><h1>A secure restart,<br><em>without losing your place.</em></h1><p>Your organisation, centres and academic records remain exactly where you left them.</p><ul><li><CheckCircle2/>At least eight characters</li><li><CheckCircle2/>Letters and numbers required</li><li><CheckCircle2/>Old remembered sessions are refreshed</li></ul></div><footer>ACADEMYHUB <span>ACCOUNT RECOVERY</span></footer></section><section class="auth-panel"><div class="auth-box"><span class="status-icon"><LockKeyhole/></span><span class="eyebrow">CHOOSE A NEW PASSWORD</span><h2>Secure your account.</h2><p>Use a strong password you do not use anywhere else.</p><form @submit.prevent="submit"><label>Email address<input v-model="form.email" type="email" autocomplete="email" required></label><label>New password<div class="password-field"><input v-model="form.password" :type="visible?'text':'password'" autocomplete="new-password" required placeholder="8+ letters and numbers"><button type="button" @click="visible=!visible"><EyeOff v-if="visible"/><Eye v-else/></button></div></label><label>Confirm new password<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required></label><div v-if="error" class="form-error">{{error}}</div><button class="button primary wide" :disabled="loading">{{loading?'Securing account…':'Save new password'}}<ArrowRight/></button></form></div></section></main></template>
